(6860653, 1032535, 37719, '<td valign="top">I get the connection, but ''implied'' is not enough for me with consideration to the challenge.</td>', 'I get the connection, but ''implied'' is not enough for me with consideration to the challenge.', '2012-09-09 22:02:56.000000', NULL, 1),
(6860656, 1032899, 37719, '<td valign="top">This is just so reminiscent of my children and now grandchildren.  I can relate to this as the capture of an instant.  But there is something with the head of the girl that just disturbs me somehow.  I don''t know how to explain it other than it doesn''t look natural.</td>', 'This is just so reminiscent of my children and now grandchildren.  I can relate to this as the capture of an instant.  But there is something with the head of the girl that just disturbs me somehow.  I don''t know how to explain it other than it doesn''t look natural.', '2012-09-09 22:06:55.000000', NULL, 1),
(6860665, 1032584, 37719, '<td valign="top">I always look at the eyes and for some reason, all four in this image seem to have a rather profound and clear impact on the image''s presentation while not necessarily being the focal point until you notice them and see.  <br/> <br/>Was this processing or lighting?  Just curious.  I will have to revisit this...</td>', 'I always look at the eyes and for some reason, all four in this image seem to have a rather profound and clear impact on the image''s presentation while not necessarily being the focal point until you notice them and see.   Was this processing or lighting?  Just curious.  I will have to revisit this...', '2012-09-09 22:13:08.000000', NULL, 1),
(6860668, 1032890, 37719, '<td valign="top">In my opinion, this is just a bit over-processed in areas.  Other than that, I love the image you created here.  The mood, the intent, the relationship is clear.  And for once, I think the title is perfectly matched with the image.  Well done.</td>', 'In my opinion, this is just a bit over-processed in areas.  Other than that, I love the image you created here.  The mood, the intent, the relationship is clear.  And for once, I think the title is perfectly matched with the image.  Well done.', '2012-09-09 22:16:38.000000', NULL, 1),
(6860670, 1032867, 37719, '<td valign="top">Wonderful expression and very interesting composition.  I like it.  Very nicely done.</td>', 'Wonderful expression and very interesting composition.  I like it.  Very nicely done.', '2012-09-09 22:18:40.000000', NULL, 1),
(6860672, 1032634, 37719, '<td valign="top">Are you asking for help or making a statement?  Either way, I will reserve vote but note image.  Something twists my spring with this.  Not sure what yet.</td>', 'Are you asking for help or making a statement?  Either way, I will reserve vote but note image.  Something twists my spring with this.  Not sure what yet.', '2012-09-09 22:22:45.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6860677, 1032778, 37719, '<td valign="top">I can see your ''view'' in a way, but the wine glass kills it when paired with your title.  Just my opinion.  Other than that, I think it would have been better with one couple or the other as the subject as opposed to both.  I find myself split, literally, and it quickly becomes a distraction.</td>', 'I can see your ''view'' in a way, but the wine glass kills it when paired with your title.  Just my opinion.  Other than that, I think it would have been better with one couple or the other as the subject as opposed to both.  I find myself split, literally, and it quickly becomes a distraction.', '2012-09-09 22:26:59.000000', NULL, 1),
(6860683, 1032875, 37719, '<td valign="top">I love how images like this force you to open your imagination and hear something never said.  I absolutely love it!  Well done.</td>', 'I love how images like this force you to open your imagination and hear something never said.  I absolutely love it!  Well done.', '2012-09-09 22:36:41.000000', NULL, 1),
(6860685, 1032614, 37719, '<td valign="top">I have the same exact comment for this image as I did for the last image of these two.  Only, here, the effect seems more profound.  Interesting.</td>', 'I have the same exact comment for this image as I did for the last image of these two.  Only, here, the effect seems more profound.  Interesting.', '2012-09-09 22:47:21.000000', NULL, 1),
(6860688, 1032895, 37719, '<td valign="top">I love the photo, just wish it wasn''t processed as much.  None of the skin looks natural and everything else looks ''polished''.</td>', 'I love the photo, just wish it wasn''t processed as much.  None of the skin looks natural and everything else looks ''polished''.', '2012-09-09 22:52:01.000000', NULL, 1),
