(6860745, 1032082, 99140, '<td valign="top">This is my favorite!!  Love the arm draped over the ducky. Very crisp!</td>', 'This is my favorite!!  Love the arm draped over the ducky. Very crisp!', '2012-09-09 23:56:53.000000', NULL, 1),
(6860748, 1032413, 99140, '<td valign="top">So many things make this so highly rated for me - the composition, the personality behind the expression, her not looking at the camera.  Good job!</td>', 'So many things make this so highly rated for me - the composition, the personality behind the expression, her not looking at the camera.  Good job!', '2012-09-09 23:58:25.000000', NULL, 1),
(6860749, 1032867, 99140, '<td valign="top">Normally I would vote so high as I did on a picture considering the background but it was well processed and to capture her face with such happiness and trust is what won me over!</td>', 'Normally I would vote so high as I did on a picture considering the background but it was well processed and to capture her face with such happiness and trust is what won me over!', '2012-09-10 00:00:19.000000', NULL, 1),
